   "sintesis": "En la vigilia que celebró ante el monumento de los Españoles en el barrio de Palermo, León XIV volvió a citar al papa Francisco y recordó la palabras que recorrieron el mundo durante la Jornada Mundial de la Juventud de Lisboa, cuando habló de una Iglesia de \"Todos, todos, todos\". El papa pidió este martes a los jóvenes que no caigan \"ante los nuevos ídolos que reclaman su adoración\", ni al éxito a cualquier precio o la obsesión por la apariencia, en la vigilia que celebró ante el monumento de los Españoles en el barrio de Palermo, en Buenos Aires, ante cerca un millón de personas.",
