   "sintesis": "Poder Judicial inaplicó leyes 32107 y 32419, según indicó porque supondría incumplimiento de obligaciones internacionales. La Sala Penal Transitoria de la Corte Suprema declaró infundadas las solicitudes de prescripción de la acción penal, bajo el amparo de las leyes 32107 y 32419, planteadas por la defensa de los sentenciados por el caso referido a la masacre de Cayara, (Ayacucho), ocurrida en 1988.",
