   "sintesis": "Las autoridades aseguran que ya han devuelto sus ahorros a muchos de los clientes de Ueno Bank, pero todavía quedan grandes cantidades por reembolsar. Ahora, el pequeño empresario pasa buena parte de sus días pendiente de su correo electrónico y de la página web del Banco Central de Paraguay (BCP), a la espera de una señal que le indique que podrá recuperar su dinero.",
   "puntos": [
    "Las autoridades aseguran que ya han devuelto sus ahorros a muchos de los clientes de Ueno Bank, pero todavía quedan grandes cantidades por reembolsar.",
    "Ahora, el pequeño empresario pasa buena parte de sus días pendiente de su correo electrónico y de la página web del Banco Central de Paraguay (BCP), a la espera de una señal que le indique que podrá recuperar su dinero.",
    "\"Me meto varias veces al día\", le dijo a BBC Mundo Vargas, quien, junto con su esposa, forma parte de los cerca de tres millones de paraguayos afectados por la caída de la entidad financiera, cuyo colapso desató una crisis política que terminó provocando la salida de Santiago Peña de la presidencia del país."
   ],
